const mapSectionInfo = await browserjs(tabId, () => {
  // Find the element containing the map or controls
  const mapBtn = document.querySelector('[aria-label*="map"], [aria-label*="Map"]');
  if (!mapBtn) return { found: false };

  // Walk up to find a container or section
  let el = mapBtn;
  const path = [];
  while (el && el !== document.body) {
    path.push({
      tagName: el.tagName,
      id: el.id,
      className: el.className,
      heading: el.querySelector('h1, h2, h3, h4')?.textContent
    });
    el = el.parentElement;
  }
  return { found: true, path };
});

